using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

public class MiscOmensHandler : ReferenceSingleton<MiscOmensHandler>
{
	[NonSerialized]
	public Func<int, CorruptionPurifyModifierEnum, GameObject, int> OnPlayerCorruptedDiademOfMadnessAction;

	[NonSerialized]
	public Func<int, int> OnPlayerCorruptedFinalModifierOmenAction;

	[NonSerialized]
	public Func<int, int> OnEnemyCorruptedDecimatorSkullModifierOmenAction;

	[NonSerialized]
	public List<Action<Dice>> OnSpecificDiceUsedActions = new List<Action<Dice>>();

	[NonSerialized]
	public List<Action<Dice>> OnSpecificDiceUsedBeforeCastActions = new List<Action<Dice>>();

	[NonSerialized]
	public Action<GameObject, GameObject> WickedsCardOmenAction;

	[NonSerialized]
	public Action<GameObject> ResetWickedsCardOmenAction;

	[NonSerialized]
	public List<Action<List<DiceInstance>>> OnPlayerRerollOmenActions = new List<Action<List<DiceInstance>>>();

	[NonSerialized]
	public List<Action<GameObject, int>> OnPlayerCorruptEnemyOmenActions = new List<Action<GameObject, int>>();

	[NonSerialized]
	public List<Action<GameObject, GameObject, int>> OnPlayerCorruptOmenActions = new List<Action<GameObject, GameObject, int>>();

	[NonSerialized]
	public List<Action<GameObject>> OnEnemyOverCorruptedOmenActions = new List<Action<GameObject>>();

	[NonSerialized]
	public BottledAuroraOmenData BottledAuroraOmenData;

	[NonSerialized]
	public List<Action> NewRuneOmenActions = new List<Action>();

	[NonSerialized]
	public Action ShuffleRunesOmenAction;

	[NonSerialized]
	public List<Action<List<Dice>>> OnStatusDiceDrawnOmenActions = new List<Action<List<Dice>>>();

	[NonSerialized]
	public Func<bool> StarChartAction;

	[NonSerialized]
	public Func<bool> SingularitySextantAction;

	[NonSerialized]
	public Action<int> DivinePrismAction;

	[NonSerialized]
	public int MeissasGiftDiscountAmount;

	[NonSerialized]
	public int SaiphsGiftDiscountAmount;

	[NonSerialized]
	public List<Action<OmenInstance>> CrimsonVaultsReachedGroundZeroActions = new List<Action<OmenInstance>>();

	[NonSerialized]
	public List<OmenInstance> CrimsonVaultsReachedGroundZeroInstances = new List<OmenInstance>();

	[NonSerialized]
	public List<StartingEffect> SentinelStartingEffectOmenList = new List<StartingEffect>();

	[NonSerialized]
	public bool SpectralHarvesterOmenActive;

	[NonSerialized]
	public Func<int, int> EntropyHoodOmenAction;

	[NonSerialized]
	public List<Action> OnPlayerPlayVirtueOmenAction = new List<Action>();

	[NonSerialized]
	public List<Action> OnPlayerSixCorruptionOmenAction = new List<Action>();

	[NonSerialized]
	public Func<int, int> SleepyPillowOmenAction;

	[NonSerialized]
	public List<Action> OnShuffleDicePoolOmenActions = new List<Action>();

	[NonSerialized]
	public Action<Dice> MysticalMagnetOmenData;

	[NonSerialized]
	public Action WealthBoxOmenAction;

	[NonSerialized]
	public Func<bool> SpicyLollipopOmenAction;

	[NonSerialized]
	public Func<bool> GlassHeartOmenAction;

	[NonSerialized]
	public DiceRewardForgeModifier ForgeSafeDiceRewardForgeModifier;

	[NonSerialized]
	public Action<int, GameObject> ShieldedCrossbowOmenAction;

	[NonSerialized]
	public bool HasStalkingJesterOmen;

	public int OnPlayerCorruptedDiademOfMadness(int corruptAmount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum, GameObject source)
	{
		if (OnPlayerCorruptedDiademOfMadnessAction != null)
		{
			return OnPlayerCorruptedDiademOfMadnessAction(corruptAmount, corruptionPurifyModifierEnum, source);
		}
		return corruptAmount;
	}

	public int OnPlayerCorruptedFinalModifier(int corruptAmount)
	{
		if (OnPlayerCorruptedFinalModifierOmenAction != null)
		{
			return OnPlayerCorruptedFinalModifierOmenAction(corruptAmount);
		}
		return corruptAmount;
	}

	public int OnEnemyCorruptedDecimatorSkullModifier(int corruptAmount)
	{
		if (OnEnemyCorruptedDecimatorSkullModifierOmenAction != null)
		{
			return OnEnemyCorruptedDecimatorSkullModifierOmenAction(corruptAmount);
		}
		return corruptAmount;
	}

	public void ActivateOnDiceUsedOmens(Dice dice)
	{
		for (int i = 0; i < OnSpecificDiceUsedActions.Count; i++)
		{
			OnSpecificDiceUsedActions[i](dice);
		}
	}

	public void ActivateOnDiceUsedOmensBeforeCast(Dice dice)
	{
		for (int i = 0; i < OnSpecificDiceUsedBeforeCastActions.Count; i++)
		{
			OnSpecificDiceUsedBeforeCastActions[i](dice);
		}
	}

	public void ActivateRerollOmens(List<DiceInstance> diceInstaces)
	{
		for (int i = 0; i < OnPlayerRerollOmenActions.Count; i++)
		{
			OnPlayerRerollOmenActions[i](diceInstaces);
		}
	}

	public void ActivateOnCorruptEnemyOmens(GameObject enemyTarget, int corruptAmount)
	{
		for (int i = 0; i < OnPlayerCorruptEnemyOmenActions.Count; i++)
		{
			OnPlayerCorruptEnemyOmenActions[i](enemyTarget, corruptAmount);
		}
	}

	public void ActivateOnCorruptOmens(GameObject target, GameObject source, int corruptAmount)
	{
		for (int i = 0; i < OnPlayerCorruptOmenActions.Count; i++)
		{
			OnPlayerCorruptOmenActions[i](target, source, corruptAmount);
		}
	}

	public void ActivateOnEnemyOverCorruptedOmens(GameObject overCorruptedEnemy)
	{
		for (int i = 0; i < OnEnemyOverCorruptedOmenActions.Count; i++)
		{
			OnEnemyOverCorruptedOmenActions[i](overCorruptedEnemy);
		}
	}

	public void ActivateBottledAuroraOmen()
	{
		if ((bool)BottledAuroraOmenData)
		{
			BottledAuroraOmenData.BottledAuroraOmenAction();
		}
	}

	public void ActivateRuneOmens()
	{
		ActivateNewRuneOmens();
		ActivateShuffleRunesOmen();
	}

	public void ActivateNewRuneOmens()
	{
		for (int i = 0; i < NewRuneOmenActions.Count; i++)
		{
			NewRuneOmenActions[i]();
		}
	}

	public void ActivateShuffleRunesOmen()
	{
		ShuffleRunesOmenAction?.Invoke();
	}

	public void ActivateOnStatusDiceDrawnOmens(List<Dice> diceList)
	{
		for (int i = 0; i < OnStatusDiceDrawnOmenActions.Count; i++)
		{
			OnStatusDiceDrawnOmenActions[i](diceList);
		}
	}

	public bool IsStarChartActiveActivateAction()
	{
		if (StarChartAction != null)
		{
			return StarChartAction();
		}
		return false;
	}

	public bool IsSingularitySextantActiveActivateAction()
	{
		if (SingularitySextantAction != null)
		{
			return SingularitySextantAction();
		}
		return false;
	}

	public void OnPlayerOrSentinelsCorruptedDivinePrismAction(int corruptionAmount)
	{
		DivinePrismAction?.Invoke(corruptionAmount);
	}

	public float GetMeissasDiscountAmount()
	{
		if (MeissasGiftDiscountAmount <= 0)
		{
			return 1f;
		}
		return (100f - (float)MeissasGiftDiscountAmount) / 100f;
	}

	public float GetSaiphsDiscountAmount()
	{
		if (SaiphsGiftDiscountAmount <= 0)
		{
			return 1f;
		}
		return (100f - (float)SaiphsGiftDiscountAmount) / 100f;
	}

	public bool IsCrimsomVaultActive()
	{
		return CrimsonVaultsReachedGroundZeroActions.Count > 0;
	}

	public void GroundZeroReachedCrimsomVaultOmen()
	{
		if (CrimsonVaultsReachedGroundZeroActions.Count > 0)
		{
			List<Action<OmenInstance>> list = CrimsonVaultsReachedGroundZeroActions.Duplicate();
			CrimsonVaultsReachedGroundZeroActions.Clear();
			for (int num = list.Count - 1; num > -1; num--)
			{
				Action<OmenInstance> action = list[num];
				OmenInstance obj = CrimsonVaultsReachedGroundZeroInstances[num];
				action(obj);
			}
		}
	}

	public void ActivateVirtueOmens()
	{
		for (int i = 0; i < OnPlayerPlayVirtueOmenAction.Count; i++)
		{
			OnPlayerPlayVirtueOmenAction[i]();
		}
	}

	public void ActivateOnPlayerSixCorruptionOmens()
	{
		for (int i = 0; i < OnPlayerSixCorruptionOmenAction.Count; i++)
		{
			OnPlayerSixCorruptionOmenAction[i]();
		}
	}

	public void ActivateOnOnShuffleDicePoolOmenActions()
	{
		for (int i = 0; i < OnShuffleDicePoolOmenActions.Count; i++)
		{
			OnShuffleDicePoolOmenActions[i]();
		}
	}

	public List<Dice> GetModifiedDiceOmenActions(List<Dice> diceList)
	{
		for (int i = 0; i < diceList.Count; i++)
		{
			if (ForgeSafeDiceRewardForgeModifier != null)
			{
				diceList[i] = ForgeSafeDiceRewardForgeModifier.GetModifiedDice(diceList[i]);
			}
		}
		return diceList;
	}
}
